import networkx as nx

# Precompute primes
MAX_SUM = 200000
is_prime_arr = [True] * (MAX_SUM + 1)
is_prime_arr[0] = is_prime_arr[1] = False
for i in range(2, int(MAX_SUM**0.5) + 1):
    if is_prime_arr[i]:
        for j in range(i*i, MAX_SUM + 1, i):
            is_prime_arr[j] = False

def solve():
    n = 100000
    A = list(range(1, n + 1))

    # Odd numbers in A need even numbers in B
    odds = [o for o in range(1, n + 1, 2)]  # odd numbers that appear in A
    evens = [e for e in range(2, n + 1, 2)]  # even numbers available for B

    G = nx.Graph()
    for o in odds:
        G.add_node(o, partition='left')
    for e in evens:
        G.add_node(e, partition='right')
    for o in odds:
        for e in evens:
            if is_prime_arr[o + e]:
                G.add_edge(o, e)

    # Find maximum matching
    matching = nx.algorithms.bipartite.maximum_matching(G, top_nodes=odds)
    # matching is a dict mapping each node to its match
    # We need to extract which even is assigned to each odd
    assignment_odd_to_even = {}  # o -> e
    for node, neighbor in matching.items():
        if node in odds:  # node is an odd number from A
            assignment_odd_to_even[node] = neighbor

    # Now construct B array
    B = [0] * n
    for o, e in assignment_odd_to_even.items():
        # o is the value in A at index o-1
        B[o - 1] = e

    # Now we need to handle even numbers in A needing odd numbers in B
    evens_A = [e for e in range(2, n + 1, 2)]  # even numbers that appear in A
    odds_B = [o for o in range(1, n + 1, 2)]    # odd numbers available for B

    G2 = nx.Graph()
    for e in evens_A:
        G2.add_node(e, partition='left')
    for o in odds_B:
        G2.add_node(o, partition='right')
    for e in evens_A:
        for o in odds_B:
            if is_prime_arr[e + o]:
                G2.add_edge(e, o)

    matching2 = nx.algorithms.bipartite.maximum_matching(G2, top_nodes=evens_A)
    assignment_even_to_odd = {}
    for node, neighbor in matching2.items():
        if node in evens_A:
            assignment_even_to_odd[node] = neighbor

    for e, o in assignment_even_to_odd.items():
        B[e - 1] = o

    # Now verify A and B are valid permutations
    # A is already [1..n]
    # B should be permutation of 1..n
    # Let's trust it but write it out
    with open('/workdir/answer.txt', 'w') as f:
        f.write(' '.join(map(str, A)) + '\n')
        f.write(' '.join(map(str, B)) + '\n')
    print("Solution generated")

if __name__ == "__main__":
    solve()
EOF"}
